function chunksNeeded(bytes, chunkBytes) {
  return Math.ceil(bytes / chunkBytes);
}

function totalMs(operations, msPerOp) {
  return operations * msPerOp;
}

function slowdownRatio(slowMs, fastMs) {
  return slowMs / fastMs;
}

function fitsInOneOperation(bytes, chunkBytes) {
  return bytes <= chunkBytes;
}

function hybridPayloadBytes(messageBytes, wrappedKeyBytes) {
  return messageBytes + wrappedKeyBytes;
}

function slowOperations(messageBytes, chunkBytes, hybrid) {
  if (hybrid) return 1;
  return Math.ceil(messageBytes / chunkBytes);
}

function hybridSavings(messageBytes, chunkBytes) {
  const direct = Math.ceil(messageBytes / chunkBytes);
  return direct - 1;
}

function cheaperPlan(messageBytes, chunkBytes, recipients) {
  const direct = recipients * Math.ceil(messageBytes / chunkBytes);
  const hybrid = recipients;
  return hybrid < direct ? "hybrid" : "direct";
}
